package com.shopsphere.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Configuration public class SecurityConfig { @Bean BCryptPasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/products","/api/health").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} }
@Component class JwtFilter extends OncePerRequestFilter { @Value("${app.jwt-secret}") String secret; public String token(String email,Long id){SecretKey k=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));return Jwts.builder().subject(email).claim("uid",id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(k).compact();} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var claims=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(h.substring(7)).getPayload();var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of());auth.setDetails(((Number)claims.get("uid")).longValue());SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}c.doFilter(r,s);} }
